import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import TimesIcon from "@/assets/icons/times.svg?react";
import InfoIcon from "@/assets/icons/info.svg?react";
import ErrorIcon from "@/assets/icons/error.svg?react";
import SuccessIcon from "@/assets/icons/success.svg?react";

import { cn } from "@/lib/utils";

type StatusIconVariant = "info" | "message" | "error" | "success";
type PillSize = "default" | "md" | "lg" | "xl";

const statusIcons = {
	info: InfoIcon,
	message: InfoIcon,
	error: ErrorIcon,
	success: SuccessIcon,
} satisfies Record<StatusIconVariant, React.ComponentType<{ className?: string }>>;

const statusIconColors = {
	info: "fill-blue",
	message: "fill-text-base",
	error: "fill-text-error",
	success: "fill-text-success",
} satisfies Record<StatusIconVariant, string>;

const pillVariants = cva(
	"pill text-3.5 inline-flex w-auto min-w-[unset] items-center gap-[0.4em] rounded-full border border-transparent px-1.75 py-0.25 leading-[1.2] transition-colors",
	{
		variants: {
			variant: {
				default: "bg-black text-white",
				error: "bg-message-error text-text-error",
				success: "bg-message-success text-text-success",
				info: "bg-message-info text-blue",
				message: "bg-message-default text-text-base",
				filter:
					"bg-grey-dark text-black hover:bg-border-light data-[state=active]:bg-red data-[state=active]:text-white data-[state=active]:hover:bg-red",
				"filter-outline":
					"hover:bg-grey-light border-2 border-grey-dark bg-white text-black data-[state=active]:border-red data-[state=active]:bg-red data-[state=active]:text-white data-[state=active]:hover:bg-red",
			},
			inverted: {
				true: "",
			},
			size: {
				default: "",
				md: "text-3.5 rounded-full px-3.5 py-1.5 font-normal",
				lg: "text-4 rounded-full px-4 py-2 font-medium",
				xl: "text-4.5 rounded-full px-5 py-2.5 font-medium",
			},
		},
		compoundVariants: [
			{
				variant: "default",
				inverted: true,
				className: "bg-black text-white",
			},
			{
				variant: "error",
				inverted: true,
				className: "bg-text-error text-white",
			},
			{
				variant: "success",
				inverted: true,
				className: "bg-text-success text-white",
			},
			{
				variant: "info",
				inverted: true,
				className: "bg-blue text-white",
			},
			{
				variant: "message",
				inverted: true,
				className: "bg-text-base text-white",
			},
		],
		defaultVariants: {
			variant: "default",
			size: "default",
			inverted: false,
		},
	},
);

export interface PillProps
	extends React.HTMLAttributes<HTMLDivElement>,
		VariantProps<typeof pillVariants> {
	/**
	 * Whether the pill is active (primarily used with filter variant)
	 */
	active?: boolean;
	/**
	 * Function called when the pill is toggled (for filter variant)
	 */
	onToggle?: () => void;
	/**
	 * Value of the pill (used for filter variant in FilterPillGroup)
	 */
	value?: string;
	/**
	 * Whether to show the icon (applies to all variants that have icons)
	 */
	showIcon?: boolean;
}

const isLargeIconSize = (size: PillSize | null | undefined) =>
	size === "md" || size === "lg" || size === "xl";

const isFilterVariant = (variant: PillProps["variant"]) =>
	variant === "filter" || variant === "filter-outline";

const PillFilterIcon = ({
	active,
	size,
}: {
	active?: boolean;
	size?: PillSize | null;
}) => {
	if (!active) {
		return null;
	}

	return (
		<TimesIcon
			className={cn("fill-white", isLargeIconSize(size) ? "size-4" : "size-3")}
		/>
	);
};

const PillStatusIcon = ({
	inverted,
	size,
	variant,
}: {
	inverted?: boolean | null;
	size?: PillSize | null;
	variant?: PillProps["variant"];
}) => {
	if (
		variant !== "info" &&
		variant !== "message" &&
		variant !== "error" &&
		variant !== "success"
	) {
		return null;
	}

	const Icon = statusIcons[variant];

	return (
		<Icon
			className={cn(
				inverted ? "fill-white" : statusIconColors[variant],
				isLargeIconSize(size) ? "size-4" : "size-3",
			)}
		/>
	);
};

const Pill = React.forwardRef<HTMLDivElement, PillProps>(
	(
		{
			className,
			variant,
			inverted,
			size,
			active,
			onToggle,
			showIcon = true,
			value: _value,
			children,
			...props
		},
		ref,
	) => {
		const isToggleable = isFilterVariant(variant) && onToggle !== undefined;

		const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
			if (isToggleable) {
				onToggle?.();
			}
			props.onClick?.(e);
		};

		const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
			if (isToggleable && (e.key === "Enter" || e.key === " ")) {
				e.preventDefault();
				onToggle?.();
			}
			props.onKeyDown?.(e);
		};

		return (
			<div
				ref={ref}
				className={cn(
					pillVariants({ variant, inverted, size, className }),
					active && "data-[state=active]",
					isToggleable && "cursor-pointer",
				)}
				data-state={active ? "active" : "inactive"}
				onClick={handleClick}
				onKeyDown={handleKeyDown}
				tabIndex={isToggleable ? 0 : undefined}
				{...props}
			>
				{showIcon && (
					<PillStatusIcon inverted={inverted} size={size} variant={variant} />
				)}
				{children}
				{showIcon && isFilterVariant(variant) && (
					<PillFilterIcon active={active} size={size} />
				)}
			</div>
		);
	},
);

Pill.displayName = "Pill";

export interface FilterPillGroupProps
	extends React.HTMLAttributes<HTMLDivElement> {
	/**
	 * The currently active filter values
	 */
	activeValues: string[];
	/**
	 * Callback when a filter value is toggled
	 */
	onValueToggle: (value: string) => void;
	/**
	 * Size variant for all pills in the group
	 */
	size?: "default" | "md" | "lg" | "xl";
	/**
	 * Whether to show icons for all pills in the group
	 */
	showIcon?: boolean;
}

const FilterPillGroup = React.forwardRef<HTMLDivElement, FilterPillGroupProps>(
	(
		{
			className,
			activeValues,
			onValueToggle,
			size = "default",
			showIcon = true,
			children,
			...props
		},
		ref,
	) => {
		// Create a map of children with toggle props
		const enhancedChildren = React.Children.map(children, (child) => {
			if (
				React.isValidElement<PillProps>(child) &&
				child.type === Pill &&
				(child.props.variant === "filter" ||
					child.props.variant === "filter-outline")
			) {
				// Get the value from the child's value prop or use the child's text content
				const value =
					child.props.value ||
					(typeof child.props.children === "string"
						? child.props.children
						: "");

				const isActive = activeValues.includes(value);

				return React.cloneElement(child as React.ReactElement<PillProps>, {
					active: isActive,
					size,
					showIcon,
					onToggle: () => onValueToggle(value),
					value,
				});
			}
			return child;
		});

		return (
			<div
				ref={ref}
				className={cn("flex flex-wrap gap-2", className)}
				{...props}
			>
				{enhancedChildren}
			</div>
		);
	},
);

FilterPillGroup.displayName = "FilterPillGroup";

export { Pill, pillVariants, FilterPillGroup };
